Here's the complete program. `FindMutualFollows` computes both the outgoing (following) and incoming (followers) sets, then reports users present in both. Note I use two different result variables for the two spawns -- reusing one variable across two different walker types is a type error in Jac:

```jac
node User {
    has username: str;
    has bio: str = "";
}

edge Follows {
    has since: str;
}

walker FindFollowers {
    can find with User entry {
        # Find all users who follow this user
        followers = [<-:Follows:<-];
        for follower in followers {
            report follower;
        }
    }
}

walker FindMutualFollows {
    can find with User entry {
        following = [here ->:Follows:->];
        followers = [here <-:Follows:<-];

        for user in following {
            if user in followers {
                report user;  # Mutual follow!
            }
        }
    }
}

with entry {
    alice = User(username="alice");
    bob = User(username="bob");
    carol = User(username="carol");

    root ++> alice;
    root ++> bob;
    root ++> carol;

    # Alice follows Bob, Bob follows Alice (mutual)
    alice +>: Follows(since="2024") :+> bob;
    bob +>: Follows(since="2024") :+> alice;

    # Carol follows Alice
    carol +>: Follows(since="2024") :+> alice;

    # Find Alice's followers
    result = alice spawn FindFollowers();
    print("Alice's followers:");
    for user in result.reports {
        print(f"  - {user.username}");
    }

    # Find Alice's mutual follows
    mutuals = alice spawn FindMutualFollows();
    print("Alice's mutual follows:");
    for user in mutuals.reports {
        print(f"  - {user.username}");
    }
}
```

Alice's followers come out as bob and carol; her only mutual is bob (she follows bob and bob follows her back; carol follows her but she doesn't follow carol).

