Got it - a fetch/filter/behaviorally-validate pipeline. I page the rows API in batches, extract only the first top-level `def`, gate it on the banned-token + allowed-import rules, `exec` it in a sandboxed namespace, call the last-defined function against a fixed input pool, and keep the first `(input, output)` that returns a non-None JSON-serializable value:

```jac
import json;
import inspect;
import builtins;
import re;
import subprocess;
import from pathlib { Path }
import from typing { Any }

glob DATASET: str = "Vezora/Tested-22k-Python-Alpaca";
glob POOL_PATH: str = "01-sft-dpo/dataset/source_pool/mined.jsonl";
glob ALLOWED_IMPORTS: list[str] = ["math", "re", "string", "functools", "collections", "itertools"];
glob BANNED: list[str] = ["np.", "pd.", "yield", "open(", "input(", "@", "class ", "async ", "lambda", "print(", "self"];
glob INPUTS: list[Any] = ["hello", "Racecar", "abcabc", "level", "Hello World",
                     5, 10, 2, 0, 7, [1, 2, 3, 4], [3, 1, 2], [5, 5, 5],
                     ["a", "b", "a"], [10, 20, 30], [2, 4, 6, 8], 2.5];


def fetch_rows(n: int) -> list[dict] {
    out: list[dict] = [];
    off: int = 0;
    while len(out) < n {
        batch: int = min(100, n - len(out));
        url: str = "https://datasets-server.huggingface.co/rows?dataset=" + DATASET
            + "&config=default&split=train&offset=" + str(off) + "&length=" + str(batch);
        p = subprocess.run(
            ["curl", "-s", "-H", "User-Agent: jacgen", url],
            capture_output=True, text=True, timeout=60
        );
        data: dict = dict(json.loads(p.stdout));
        rows: list = list(data["rows"]);
        if len(rows) == 0 { break; }
        for r in rows {
            row: dict = dict(r["row"]);
            out.append(row);
        }
        off += batch;
    }
    return out;
}


def first_func(code: str) -> str {
    lines: list[str] = code.split("\n");
    start: int = -1;
    for (i, l) in enumerate(lines) {
        if l.startswith("def ") { start = i; break; }
    }
    if start < 0 { return ""; }
    blk: list[str] = [lines[start]];
    for l in lines[start + 1:] {
        if l.strip() == "" or l.startswith(" ") or l.startswith("\t") { blk.append(l); }
        else { break; }
    }
    return "\n".join(blk).rstrip();
}


def is_clean(code: str) -> bool {
    head: str = code.split("\n")[0];
    if "*" in head { return False; }
    for b in BANNED { if b in code { return False; } }
    imports: list = list(re.findall("(?:^\\s*import |^\\s*from )(\\w+)", code, re.M));  # jac:ignore[E1054]
    for m in imports { if m not in ALLOWED_IMPORTS { return False; } }
    if re.search("\\breturn\\s+\\S", code) is None { return False; }
    nlines: int = len(code.split("\n"));
    return nlines > 1 and nlines <= 14;
}


def try_run(code: str) -> dict {
    ns: dict = {};
    try {
        exec(code, {"__builtins__": builtins}, ns);
    } except Exception {  # jac:ignore[W2052] mined code can raise anything
        return {"ok": False};
    }
    funcs: list = [];
    names: list[str] = [];
    for (k, v) in ns.items() {
        if callable(v) and not k.startswith("__") {
            funcs.append(v);
            names.append(str(k));
        }
    }
    if len(funcs) == 0 { return {"ok": False}; }
    fn = funcs[-1];
    name: str = names[-1];
    try {
        params = inspect.signature(fn).parameters;  # jac:ignore[E1053]
        if len(params) != 1 { return {"ok": False}; }
    } except (ValueError, TypeError) {
        return {"ok": False};
    }
    for a in INPUTS {
        try {
            o = fn(a);
        } except Exception {  # jac:ignore[W2052] mined code can raise anything
            continue;
        }
        if o is None { continue; }
        if isinstance(o, (int, float, str, bool, list, dict)) {
            return {"ok": True, "name": name, "input": a, "output": o};
        }
    }
    return {"ok": False};
}


def mine(scan: int, limit: int) -> list[dict] {
    rows: list[dict] = fetch_rows(scan);
    kept: list[dict] = [];
    for r in rows {
        if len(kept) >= limit { break; }
        output: str = str(r["output"]);
        src: str = first_func(output);
        if src == "" or not is_clean(src) { continue; }
        res: dict = try_run(src);
        ok: bool = bool(res["ok"]);
        if not ok { continue; }
        name: str = str(res["name"]);
        call_input = res["input"];
        expected = res["output"];
        kept.append({
            "func_name": name,
            "python": src,
            "call_input": call_input,
            "expected_output": expected,
            "source": DATASET
        });
    }
    return kept;
}


def write_pool(items: list[dict]) {
    p = Path(POOL_PATH);
    p.parent.mkdir(parents=True, exist_ok=True);
    with open(POOL_PATH, "w") as f {
        for it in items { f.write(json.dumps(it) + "\n"); }
    }
}


with entry {
    items: list[dict] = mine(400, 40);
    write_pool(items);
    print("mined " + str(len(items)) + " runnable functions -> " + POOL_PATH);
    for it in items[:10] {
        fname: str = str(it["func_name"]);
        print("  " + fname);
    }
}
```

Run it from the repo root with `jac run srccurrent/jacgen/mine.jac`. The banned-token scan plus the `exec`-then-call step is what makes every kept row genuinely runnable, so the recorded `expected_output` is real ground truth.

Here's the script. I parse each `Iter N` line with a small regex helper (returns -1.0 when a metric is absent so I can skip it), collect `[iteration, value]` points per metric, then render each with a shared `plot_one`. `matplotlib.use("Agg")` keeps it headless, and the paths read from `JAC_TRAIN_LOG` / `JAC_METRICS` / `JAC_PLOT_DIR`:

```jac
import json;
import re;
import os;
import matplotlib;
import from matplotlib { pyplot }
import from pathlib { Path }
import from typing { Any }


def _num(line: str, pattern: str) -> float {
    m = re.search(pattern, line);
    if m is None { return -1.0; }
    return float(str(m.group(1)));
}


def parse_train(path: str) -> dict {
    train: list = [];
    val: list = [];
    lr: list = [];
    tps: list = [];
    itsec: list = [];
    trained: list = [];
    peak: list = [];
    p = Path(path);
    if not p.exists() {
        return {"train": train, "val": val, "lr": lr, "tps": tps,
                "itsec": itsec, "trained": trained, "peak": peak};
    }
    for line in p.read_text().split("\n") {
        m = re.search("Iter (\\d+)", line);
        if m is None { continue; }
        it: int = int(str(m.group(1)));
        tl: float = _num(line, "Train loss ([0-9.]+)");
        if tl >= 0.0 { train.append([it, tl]); }
        vl: float = _num(line, "Val loss ([0-9.]+)");
        if vl >= 0.0 { val.append([it, vl]); }
        lv: float = _num(line, "Learning Rate ([0-9.eE+-]+)");
        if lv >= 0.0 { lr.append([it, lv]); }
        tv: float = _num(line, "Tokens/sec ([0-9.]+)");
        if tv >= 0.0 { tps.append([it, tv]); }
        iv: float = _num(line, "It/sec ([0-9.]+)");
        if iv >= 0.0 { itsec.append([it, iv]); }
        ttv: float = _num(line, "Trained Tokens ([0-9]+)");
        if ttv >= 0.0 { trained.append([it, ttv]); }
        pv: float = _num(line, "Peak mem ([0-9.]+)");
        if pv >= 0.0 { peak.append([it, pv]); }
    }
    return {"train": train, "val": val, "lr": lr, "tps": tps,
            "itsec": itsec, "trained": trained, "peak": peak};
}


def plot_one(points: list, title: str, ylabel: str, outpath: str) {
    if len(points) == 0 { return; }
    xs: list = [p[0] for p in points];
    ys: list = [p[1] for p in points];
    pyplot.figure();  # jac:ignore[E1051]
    pyplot.plot(xs, ys, marker="o");  # jac:ignore[E1051,E1052]
    pyplot.title(title);  # jac:ignore[E1051]
    pyplot.xlabel("iteration");  # jac:ignore[E1051]
    pyplot.ylabel(ylabel);  # jac:ignore[E1051]
    pyplot.grid(True);  # jac:ignore[E1051]
    pyplot.savefig(outpath);  # jac:ignore[E1051]
    pyplot.close();  # jac:ignore[E1051]
    print("  wrote " + outpath);
}


with entry {
    matplotlib.use("Agg");
    train_log: str = os.environ.get("JAC_TRAIN_LOG", "01-sft-dpo/results/train.log");
    metrics: str = os.environ.get("JAC_METRICS", "01-sft-dpo/results/metrics.jsonl");
    d: str = os.environ.get("JAC_PLOT_DIR", "results");   # per-model output dir (e.g. 01-sft-dpo/results/qwen)

    t: dict = parse_train(train_log);
    plot_one(list(t["train"]), "Train Loss", "loss", d + "/train_loss.png");
    plot_one(list(t["val"]), "Validation Loss", "loss", d + "/val_loss.png");
    plot_one(list(t["lr"]), "Learning Rate", "lr", d + "/learning_rate.png");
    plot_one(list(t["tps"]), "Throughput", "tokens/sec", d + "/tokens_per_sec.png");
    plot_one(list(t["itsec"]), "Iterations/sec", "it/sec", d + "/iters_per_sec.png");
    plot_one(list(t["trained"]), "Trained Tokens (cumulative)", "tokens", d + "/trained_tokens.png");
    plot_one(list(t["peak"]), "Peak Memory", "GB", d + "/peak_mem.png");

    lc: list = [];
    mp = Path(metrics);
    if mp.exists() {
        for line in mp.read_text().split("\n") {
            if not line.strip().startswith("{") { continue; }   # skip blank/partial lines
            r: dict = dict(json.loads(line));
            lc.append([r["step"], r["test_pass_pct"]]);
        }
    }
    plot_one(lc, "Holdout test-pass % per checkpoint (learning curve)", "test-pass %",
             d + "/learning_curve.png");
    print("graphs in " + d + "/");
}
```

The learning-curve section skips any blank/partial jsonl lines so a half-flushed metrics file won't crash the run.

Here's the builder. It parses the HOLE region, runs each driver in a `TemporaryDirectory` cwd (twice, for the determinism guard), writes a `__HOLE__` template plus a reference-body sidecar, and emits one `{prompt, answer}` per driver into `tasks.jsonl`:

```jac
import os;
import re;
import json;
import glob;
import subprocess;
import from pathlib { Path }

def run_jac(jac_code: str, timeout: int = 30) -> tuple[int, str, str] {
    # Mirror of 01-sft-dpo/sft_dpo/jacgen/writer.jac:run_jac — the behavioral gate.
    import tempfile;
    with tempfile.TemporaryDirectory() as d {
        f = Path(str(d)) / "snippet.jac";
        f.write_text(jac_code);
        try {
            # cwd=d so jac's `.jac/` persistence is fresh per run (a persistent
            # `root` graph would otherwise accumulate state across drivers).
            p = subprocess.run(
                ["jac", "run", str(f)], capture_output=True, text=True, timeout=timeout, cwd=str(d)
            );
            return (p.returncode, p.stdout, p.stderr);
        } except (subprocess.SubprocessError, OSError) as e {
            return (124, "", str(e));
        }
    }
}

def parse_hole(text: str) -> dict {
    # Returns {ok, id, instruction, indent, start, end} where start/end are line
    lines = text.split("\n");
    start = -1;
    end = -1;
    for (i, ln) in enumerate(lines) {
        if ">>>HOLE" in ln { start = i; }
        elif "<<<HOLE" in ln { end = i; }
    }
    if start < 0 or end < 0 or end <= start {
        return {"ok": False};
    }
    m = re.search(r'>>>HOLE\s+id="([^"]+)"\s+instruction="(.*)"', lines[start]);
    if not m {
        return {"ok": False};
    }
    indent = re.match(r"\s*", lines[start]).group(0);
    return {
        "ok": True,
        "id": str(m.group(1)),
        "instruction": str(m.group(2)),
        "indent": indent,
        "start": start,
        "end": end,
        "lines": lines
    };
}

def replace_region(lines: list, start: int, end: int, repl_lines: list) -> str {
    out = lines[:start] + repl_lines + lines[end + 1:];
    return "\n".join(out);
}

def sg_bucket(tid: str) -> str {
    # social_graph.jac is one 32-task file (~half the corpus) — too big to hold out
    # whole, so its OSP-walker idiom can never sit in a file-disjoint holdout. Split
    # it into 4 feature buckets so build_rl_splits can reserve a coherent sg slice
    # (e.g. all 'tweet' walkers) and measure sg-idiom generalization.
    if "channel" in tid { return "channel"; }
    if ("tweet" in tid) or ("comment" in tid) or ("like" in tid) { return "tweet"; }
    if "profile" in tid { return "profile"; }
    return "feed";   # feed / follow / trending / user / etc.
}

with entry {
    drivers = sorted(glob.glob("02-rl-grpo/rl/drivers/*.jac"));
    os.makedirs("02-rl-grpo/dataset/rl/templates", exist_ok=True);
    tasks_path = "02-rl-grpo/dataset/rl/tasks.jsonl";
    open(tasks_path, "w").close();   # truncate — full rebuild each run

    built = 0;
    failed = 0;
    for path in drivers {
        text = Path(path).read_text();
        info = parse_hole(text);
        if not info["ok"] {
            print("SKIP (no valid HOLE): " + path);
            failed += 1;
            continue;
        }
        # ground-truth output: run the driver exactly as authored
        (code, out, err) = run_jac(text);
        if code != 0 or not out.strip() {
            print("FAIL (driver did not run clean): " + path + "  exit=" + str(code));
            print("   " + err.strip()[:200]);
            failed += 1;
            continue;
        }
        # determinism guard: a task whose stdout varies run-to-run is unusable as
        # an exact-match RL target (jid()/time/unseeded-rng leak). Re-run once.
        (code2, out2, err2) = run_jac(text);
        if out2 != out {
            print("FAIL (NONDETERMINISTIC stdout): " + path);
            failed += 1;
            continue;
        }
        # origin source file (for file-disjoint holdout in build_rl_splits.jac)
        src_m = re.search(r"Origin:\s*(this_is_jac/\S+?\.jac)", text);
        source = str(src_m.group(1)) if src_m else "unknown";
        # OPT-IN (JAC_RL_SG_BUCKETS=1): bucket the one big social_graph.jac into
        # feature sub-sources so its idiom can be held out file-disjoint. Off by
        # default so the established gb+lib-holdout ladder stays reproducible; the
        # step-7 sg-generalization run turns it on (+ its own results file).
        if ("social_graph.jac" in source) and (os.environ.get("JAC_RL_SG_BUCKETS", "") == "1") {
            source = source + "::" + sg_bucket(info["id"]);
        }

        lines = info["lines"];
        indent = info["indent"];
        # template: body region -> a single __HOLE__ sentinel line
        template = replace_region(lines, info["start"], info["end"], [indent + "__HOLE__"]);
        # prompt view: body region -> a TODO placeholder
        prompt_view = replace_region(
            lines, info["start"], info["end"],
            [indent + "# TODO: write the body for this unit"]
        );
        prompt = (
            info["instruction"]
            + "\n\nComplete the Jac file below: replace the `# TODO` line with the"
            + " correct Jac code for that unit. Return only the replacement code,"
            + " in a ```jac code block.\n\n```jac\n" + prompt_view + "\n```"
        );

        Path("02-rl-grpo/dataset/rl/templates/" + info["id"] + ".jac").write_text(template);
        # reference body (between the sentinels) -> sidecar, used by the reward's
        # dense similarity-shaping term (NOT shown to the model; reward-side only).
        ref_body = "\n".join(lines[info["start"] + 1:info["end"]]);
        os.makedirs("02-rl-grpo/dataset/rl/refbodies", exist_ok=True);
        Path("02-rl-grpo/dataset/rl/refbodies/" + info["id"] + ".txt").write_text(ref_body);
        rec = {
            "prompt": prompt,
            "answer": json.dumps({
                "id": info["id"],
                "source": source,
                "expected_output": out,
                "timeout": 20
            })
        };
        with open(tasks_path, "a") as fh {
            fh.write(json.dumps(rec) + "\n");
        }
        built += 1;
        print("OK  " + info["id"] + "  (" + str(len(out.strip().split(chr(10)))) + " output lines)");
    }
    print("=== built " + str(built) + " tasks, " + str(failed) + " failed -> " + tasks_path + " ===");
}
```

The `sg_bucket` split only kicks in when `JAC_RL_SG_BUCKETS=1`, so by default you get the established gb+lib holdout ladder unchanged.

