So we need cos/sin without `math`. I'll add range-reduced Taylor helpers `jcos`/`jsin`, then `fire`. Here's the aim math first:

```jac
def fire(bullets: list[Bullet]) -> None {
    yaw_r = yaw * DEG2RAD;
    pitch_r = pitch * DEG2RAD;
    dx = -jsin(yaw_r);
    dy = jsin(pitch_r);
    dz = -jcos(yaw_r);
    # place first dead bullet...
}
```

But that ignores the pitch when computing the horizontal components - the aim would be wrong when looking up/down. Should I scale dx/dz by cos(pitch)?

Here's the complete file. `jcos`/`jsin` are the range-reduced Taylor helpers, and `fire` builds the aim with `cp = jcos(pitch_r)` scaling `dx`/`dz`, then reuses the first dead pool slot:

```jac
glob DEG2RAD: float = 0.017453292519943295,
     yaw: float = 30.0,
     pitch: float = 15.0,
     px: float = 1.0,
     py: float = 2.0,
     pz: float = 3.0;

obj Bullet {
    has x: float,
        y: float,
        z: float,
        vx: float,
        vy: float,
        vz: float,
        life: float;
}

"""cos via range-reduced Taylor series (good to ~1e-4 on the reduced range)."""
def jcos(a: float) -> float {
    twopi = 6.283185307179586;
    pi = 3.141592653589793;
    while a > pi {
        a -= twopi;
    }
    while a < -pi {
        a += twopi;
    }
    x2 = a * a;
    x4 = x2 * x2;
    x6 = x4 * x2;
    x8 = x4 * x4;
    x10 = x8 * x2;
    x12 = x8 * x4;
    return 1.0 - x2 / 2.0 + x4 / 24.0 - x6 / 720.0 + x8 / 40320.0 - x10 / 3628800.0 + x12 / 479001600.0;
}

"""sin(a) = cos(a - pi/2)."""
def jsin(a: float) -> float {
    return jcos(a - 1.5707963267948796);
}

def fire(bullets: list[Bullet]) -> None {
    yaw_r = yaw * DEG2RAD;
    pitch_r = pitch * DEG2RAD;
    cp = jcos(pitch_r);
    dx = -jsin(yaw_r) * cp;
    dy = jsin(pitch_r);
    dz = -jcos(yaw_r) * cp;
    speed = 40.0;
    i = 0;
    while i < len(bullets) {
        b = bullets[i];
        if b.life <= 0.0 {
            b.x = px;
            b.y = py;
            b.z = pz;
            b.vx = dx * speed;
            b.vy = dy * speed;
            b.vz = dz * speed;
            b.life = 2.0;
            return;
        }
        i += 1;
    }
}

with entry {
    bullets = [
        Bullet(x=0.0, y=0.0, z=0.0, vx=0.0, vy=0.0, vz=0.0, life=5.0),
        Bullet(x=0.0, y=0.0, z=0.0, vx=0.0, vy=0.0, vz=0.0, life=0.0)
    ];
    fire(bullets);
    b = bullets[1];
    print(
        str(round(b.x, 6)) + " " + str(round(b.y, 6)) + " " + str(round(b.z, 6))
        + " " + str(round(b.vx, 6)) + " " + str(round(b.vy, 6)) + " "
        + str(round(b.vz, 6)) + " " + str(round(b.life, 6))
    );
}
```

Scanning from index 0 for the first `life <= 0` slot and returning immediately means one shot reuses exactly one slot per call.

