def main():
    # DAG as dict-of-lists adjacency (prereq -> dependents)
    nodes = ["A", "B", "C", "D", "E"]
    edges = [("A", "B"), ("A", "C"), ("B", "D"), ("C", "D"), ("D", "E")]

    succ = {n: [] for n in nodes}
    indeg = {n: 0 for n in nodes}
    for u, v in edges:
        succ[u].append(v)
        indeg[v] += 1

    # Kahn's algorithm with alphabetical tie-break for determinism
    order = []
    available = sorted([n for n in nodes if indeg[n] == 0])
    while available:
        cur = available.pop(0)
        order.append(cur)
        for v in succ[cur]:
            indeg[v] -= 1
            if indeg[v] == 0:
                available.append(v)
        available.sort()

    print(order)


if __name__ == "__main__":
