    has rejected: int = 0;
    has history: list = [];

    def apply(op: dict) -> None {
        match op["kind"] {
            case "dep":
                self.balance += op["amt"];
                self.history.append(op["amt"]);
            case "wd":
                if op["amt"] > self.balance {
                    self.rejected += 1;
                } else {
                    self.balance -= op["amt"];
                    self.history.append(-op["amt"]);
                }
        }
    }

    def summary -> list {
        return [self.balance, self.rejected, len(self.history)];
    }
}

