def insertion_sort(arr: Any) -> object {
    comparisons = 0;
    for i in range(1, len(arr)) {
        key = arr[i];
        j = i - 1;
        while ((j >= 0) and (key < arr[j])) {
            comparisons += 1;
            arr[(j + 1)] = arr[j];
            j -= 1;
        }
        arr[(j + 1)] = key;
    }
    return comparisons;
}



